Method.Source:
    /// <summary>
    /// Retrieves the first record of the table based on condition
    /// </summary>
    /// <param name = "_custAccount"> Customer account number</param>
    /// <param name = "_liquorLicenceNumber"> Customer's Liquor licence number</param>
    /// <param name = "_forUpdate"> A Boolean value that determines whether the RecId of orign should be selected for update; optional.</param>
    /// <returns> The table record </returns>
    static METCustLiquorLicenseTable find(CustAccount   _custAccount, METLiquorLicenceNumber  _liquorLicenceNumber, boolean  _forUpdate = false)
    {
        METCustLiquorLicenseTable custLiquorLicenseTable;

        if (_custAccount && _liquorLicenceNumber)
        {
            if (_forUpdate)
            {
                custLiquorLicenseTable.selectForUpdate(_forUpdate);
            }

            select firstonly custLiquorLicenseTable
                index hint CustLiquorIdx
                where custLiquorLicenseTable.CustomerNumber == _custAccount
                   && custLiquorLicenseTable.LiquorLicenceNumber == _liquorLicenceNumber;
        }

        return custLiquorLicenseTable;
    }

/// <summary>
/// Searches for the first record of the table based on condition
/// </summary>
/// <param name = "_custAccount"> Customer account number</param>
/// <param name = "_liquorLicenceNumber"> Customer's Liquor licence number</param>
/// <returns> A Boolean value "Yes" if record exists, else "No" </returns>
static boolean exist(CustAccount _custAccount, METLiquorLicenceNumber  _liquorLicenceNumber)
{
    return _custAccount && (select firstonly RecId from METCustLiquorLicenseTable
                                index hint CustLiquorIdx
                                where METCustLiquorLicenseTable.CustomerNumber == _custAccount
                                   && METCustLiquorLicenseTable.LiquorLicenceNumber == _liquorLicenceNumber).RecId != 0;
}

    /// <summary>
    /// Customer Liquor validations on modified fields
    /// </summary>
    /// <param name = "_fieldId">Field number of the modified column</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);
        switch(_fieldId)
        {
            case fieldnum(METCustLiquorLicenseTable, CustomerNumber):
                CustTable custTable;
                select firstonly AccountNum, Party from custTable index hint AccountIdx where custTable.AccountNum == this.CustomerNumber;
                if(custTable.AccountNum)
                {
                    this.CustomerName = custTable.name();
                }
                break;

        }
    }
